<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use Illuminate\Support\Facades\DB;
class CampaignController extends Controller{public function active(){return DB::table('sale_campaigns')->where('is_active',true)->where('starts_at','<=',now())->where('ends_at','>=',now())->orderBy('sort_order')->get()->map(function($c){$c->products=\App\Models\Product::whereHas('variants',fn($q)=>$q->whereIn('id',DB::table('sale_campaign_items')->where('campaign_id',$c->id)->pluck('variant_id')))->with(['media','variants'=>function($q)use($c){$q->leftJoin('sale_campaign_items as sci',fn($j)=>$j->on('sci.variant_id','=','product_variants.id')->where('sci.campaign_id',$c->id))->select('product_variants.*','sci.sale_price','sci.stock_limit','sci.sold');}])->limit(12)->get();return $c;});}}
